steps.script:
# The fixture really is a full, empty Ork mirror on the crucible triangle with
# NO declared reserves and no attached leaders yet - so any unit in reserves
# after deployment was forced there.
var und = {1: 0, 2: 0}
var res = 0
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	var s = int(u.get("status", 0))
	if s == 0:
		und[int(u.owner)] += 1
	elif s == 7:
		res += 1
print("SCENARIO ai_deploy_p0 precondition: undeployed P1=%d P2=%d reserves=%d zone=%s" % [und[1], und[2], res, str(GameState.state.meta.get("deployment_type", "?"))])
return "%d|%d|%d|%s" % [und[1], und[2], res, str(GameState.state.meta.get("deployment_type", "?"))]

# Deployment ended, the AI stopped there, and nothing moved afterwards: the
# game waits at the first-turn roll-off (REDEPLOYMENT auto-skips - no unit in
# this fixture can redeploy) with both AI seats off and the board digest
# (positions, statuses, embarks, attachments) equal to the one latched the
# instant deployment ended.
var latch = GameState.get_meta("ai_deploy_p0_latch", {})
var moved = DeploymentEval.positions_digest(GameState.state) != str(latch.get("digest", ""))
var ai_on = AIPlayer.is_ai_player(1) or AIPlayer.is_ai_player(2)
print("SCENARIO ai_deploy_p0 stop: latched_phase=%s phase_now=%d ai_on=%s moved=%s" % [str(latch.get("phase", "?")), GameState.get_current_phase(), str(ai_on), str(moved)])
return "%d|%s|%s" % [GameState.get_current_phase(), str(ai_on), str(moved)]

# Legal by construction: the phase never refused ANY deployment action the AI
# sent - counted at the source by AIPlayer for every deployment action type
# (DEPLOY_UNIT, COMPOSITE_DEPLOY, EMBARK_UNITS_DEPLOYMENT, PLACE_IN_RESERVES,
# ATTACH_CHARACTER_DEPLOYMENT) and every route (first try, retry, reserves
# fallback) - plus the legacy Game Log count of first-try rejections.
var recs = AIPlayer.get_deploy_rejections()
var a = DeploymentEval.count_rejected_deploy_actions(recs, 1)
var b = DeploymentEval.count_rejected_deploy_actions(recs, 2)
var la = DeploymentEval.count_failed_deploy_attempts(GameEventLog.entries, 1)
var lb = DeploymentEval.count_failed_deploy_attempts(GameEventLog.entries, 2)
print("SCENARIO ai_deploy_p0 rejected P1=%d P2=%d (legacy game log P1=%d P2=%d) %s" % [a, b, la, lb, str(recs)])
return "%d|%d|%d|%d" % [a, b, la, lb]

# 19.01: each attached Wartrike was set up WITH its Warbikers in one
# COMPOSITE_DEPLOY (combined_char_data placed by the formation builder), and
# is on the table now.
var comp = {1: 0, 2: 0}
for e in AIPlayer.get_action_log():
	if str(e.get("action_type", "")) == "COMPOSITE_DEPLOY":
		var pl = int(e.get("player", 0))
		comp[pl] = int(comp.get(pl, 0)) + 1
var placed = 0
for cid in ["U_DEFFKILLA_WARTRIKE_A", "U_DEFFKILLA_WARTRIKE_B", "U_DEFFKILLA_WARTRIKE_A_P2", "U_DEFFKILLA_WARTRIKE_B_P2"]:
	var cu = GameState.state.units[cid]
	if int(cu.get("status", 0)) == 2 and DeploymentEval.is_on_table(cu):
		placed += 1
print("SCENARIO ai_deploy_p0 attached: COMPOSITE_DEPLOY P1=%d P2=%d, leaders on the table %d/4" % [comp[1], comp[2], placed])
return "%d|%d|%d" % [comp[1], comp[2], placed]

# UI: every model on the table (a DEPLOYED, non-embarked unit) is drawn
# exactly once on the board - attached leaders included.
var tl = tree.current_scene.get_node_or_null("BoardRoot/TokenLayer")
if tl == null:
	return "no TokenLayer"
var drawn = {}
for c in tl.get_children():
	if c.has_meta("unit_id") and c.has_meta("model_id"):
		var k = str(c.get_meta("unit_id"))
		drawn[k] = int(drawn.get(k, 0)) + 1
var bad = []
var checked = 0
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("status", 0)) != 2:
		continue
	var emb = u.get("embarked_in", null)
	if emb != null and str(emb) != "":
		continue
	checked += 1
	var n = 0
	for m in u.get("models", []):
		if m.get("alive", true) and m.get("position", null) != null:
			n += 1
	if int(drawn.get(uid, 0)) != n:
		bad.append("%s %d/%d" % [uid, int(drawn.get(uid, 0)), n])
print("SCENARIO ai_deploy_p0 tokens: %d units checked, mismatches %s" % [checked, str(bad)])
return ("ok %d" % checked) if bad.is_empty() else ", ".join(bad)

# UI: the off-board reserves rails list nothing for either player (in the
# pre-fix baseline they listed 4-5 Ork units a side). Only the id lists are
# asserted: whether a rail is drawn also depends on gutter width and zoom.
var tray = tree.current_scene.get_node_or_null("ReservesTray")
if tray == null:
	return "no ReservesTray"
var a = tray.visible_unit_ids_for(1)
var b = tray.visible_unit_ids_for(2)
print("SCENARIO ai_deploy_p0 tray: P1=%s P2=%s" % [str(a), str(b)])
return "%d|%d" % [a.size(), b.size()]

# Hygiene: disconnect the stop hook, drop the scenario's meta, and put the AI
# seats, AI speeds, game_config seat types and the plans override back as the
# scenario found them.
var h = GameState.get_meta("ai_deploy_p0_hook", null)
var was_connected = h != null and PhaseManager.phase_changed.is_connected(h)
if was_connected:
	PhaseManager.phase_changed.disconnect(h)
var saved = GameState.get_meta("ai_deploy_p0_saved", {})
if not saved.is_empty():
	if bool(saved.get("had_game_config", false)) and saved.get("game_config", null) is Dictionary:
		GameState.state["meta"]["game_config"] = saved.get("game_config")
	else:
		GameState.state["meta"].erase("game_config")
	var seats = saved.get("ai_players", {})
	AIPlayer.configure({1: "AI" if bool(seats.get(1, false)) else "HUMAN", 2: "AI" if bool(seats.get(2, false)) else "HUMAN"})
	AIPlayer.enabled = bool(saved.get("enabled", false))
	AIPlayer.set_ai_speed_preset(int(saved.get("speed_preset", 1)))
	AIPlayer.set_spectator_speed_index(int(saved.get("spectator_index", 2)))
AIDecisionMaker._config_overrides.erase("PLANS_ENABLED")
for k in ["ai_deploy_p0_latch", "ai_deploy_p0_hook", "ai_deploy_p0_saved"]:
	if GameState.has_meta(k):
		GameState.remove_meta(k)
var still = h != null and PhaseManager.phase_changed.is_connected(h)
var ai_on = AIPlayer.is_ai_player(1) or AIPlayer.is_ai_player(2)
print("SCENARIO ai_deploy_p0 cleanup: hook was connected=%s still=%s ai_on=%s" % [str(was_connected), str(still), str(ai_on)])
return "%s|%s|%s|%s|%s" % [str(was_connected), str(still), str(GameState.has_meta("ai_deploy_p0_latch")), str(AIDecisionMaker._config_overrides.has("PLANS_ENABLED")), str(ai_on)]
